sys_ux_client_script.script:
function handler({api, event, helpers, imports}) {

    var results = api.data.look_up_multiple_records_2.results || [];

    var leaderboard = results.map(function(record) {

        return {
            value: {
                participant: record.participant,
                response_time: record.response_time,
                buzzer_time: record.buzzer_time,
                run_number: record.run_number
            }
        };

    });

    api.setState("leaderboardData", leaderboard);
}
